using Jellyfin.RequestHub;
using System.Net;
using System.Text.Json;
int checks=0;
void Check(bool result,string message){if(!result)throw new Exception(message);checks++;}
var a=Guid.NewGuid();var b=Guid.NewGuid();var links=new[]{new UserLink{JellyfinUserId=a,SeerrUserId=17,AllowRequests=true}};
Check(HubPolicy.OwnMapping(links,a)?.SeerrUserId==17,"Mapped identity is selected");
Check(HubPolicy.OwnMapping(links,b)is null,"Unmapped identities never fall back to administrator");
Check(HubPolicy.OwnMapping(links,Guid.Empty)is null,"Empty identity fails closed");
foreach(var bad in new[]{"file:///etc/passwd","http://user:pass@host","https://host?key=secret","https://host/#f"}){try{HubPolicy.BaseUri(bad);throw new Exception("URL accepted");}catch(ArgumentException){checks++;}}
Check(HubPolicy.BaseUri("http://host/base").AbsoluteUri=="http://host/base/api/v1/","Base URL retains path prefix");
Check(HubPolicy.BrowsePath("search",2,"a&admin=true",null).EndsWith("query=a%26admin%3Dtrue"),"Search cannot inject upstream parameters");
Check(HubPolicy.BrowsePath("network",1,null,213)=="discover/tv/network/213?page=1","Network browse path maps to TV network endpoint");
try{HubPolicy.BrowsePath("../settings",1,null,null);throw new Exception("Path accepted");}catch(ArgumentException){checks++;}
Check(HubPolicy.RequestValid("movie",1,[]),"Movie requests validate");Check(HubPolicy.RequestValid("tv",1,[1,2]),"Specific seasons validate");
Check(!HubPolicy.RequestValid("tv",1,[]),"TV needs explicit seasons");Check(!HubPolicy.RequestValid("tv",1,[1,1]),"Duplicate seasons rejected");Check(!HubPolicy.RequestValid("person",1,[]),"Unsupported media rejected");
Check(HubPolicy.Poster("/image.jpg")is not null&&HubPolicy.Poster("//evil.test/image.jpg")is null,"Poster origin is restricted");
Check(HubPolicy.Backdrop("/backdrop.jpg")=="/backdrop.jpg"&&HubPolicy.Backdrop("//evil.test/backdrop.jpg")is null,"Backdrop path is validated");
var html="<html><body></body></html>";var patched=WebMarkup.Inject(html,"0.4.0.0",true);Check(patched.Contains("../RequestHub/Assets/web.js"),"Independent browser delivery path");Check(WebMarkup.Inject(patched,"0.4.0.0",true)==patched,"No duplicate script");
using(var doc=JsonDocument.Parse("{\"id\":1,\"title\":\"Movie\",\"posterPath\":\"/image.jpg\",\"releaseDate\":\"2020-05-01\",\"voteCount\":50,\"apiKey\":\"secret\",\"requestedBy\":{\"email\":\"private\"}}")){var safe=JsonSerializer.Serialize(Projection.Item(doc.RootElement,"movie"));Check(!safe.Contains("secret")&&!safe.Contains("private"),"Projection excludes secrets and user records");Check(Projection.IsReleased(doc.RootElement,new DateOnly(2026,1,1)),"Released title with votes passes");}
using(var doc=JsonDocument.Parse("{\"id\":2,\"title\":\"Future Movie\",\"releaseDate\":\"2027-12-18\",\"voteCount\":0}")){Check(!Projection.IsReleased(doc.RootElement,new DateOnly(2026,11,6)),"Unreleased future title is excluded");}
using(var doc=JsonDocument.Parse("{\"id\":101,\"mediaType\":\"movie\",\"title\":\"Already Downloaded\",\"releaseDate\":\"2022-05-01\",\"voteCount\":100,\"mediaInfo\":{\"status\":5}}")){Check(!Projection.ShouldIncludeBrowseItem(doc.RootElement,"movie",new DateOnly(2026,11,6)),"Seerr available status=5 movie is excluded from Discover");}
using(var doc=JsonDocument.Parse("{\"id\":202,\"mediaType\":\"movie\",\"title\":\"In Jellyfin Library\",\"releaseDate\":\"2022-05-01\",\"voteCount\":100}")){Check(!Projection.ShouldIncludeBrowseItem(doc.RootElement,"movie",new DateOnly(2026,11,6),new HashSet<int>{202},null),"Playable Jellyfin library movie is excluded from Discover");}
using(var doc=JsonDocument.Parse("{\"id\":303,\"mediaType\":\"tv\",\"name\":\"Partly Available Show\",\"firstAirDate\":\"2022-05-01\",\"voteCount\":100,\"mediaInfo\":{\"status\":4}}")){Check(Projection.ShouldIncludeBrowseItem(doc.RootElement,"tv",new DateOnly(2026,11,6),null,new HashSet<int>{303}),"Partly available series remains requestable for missing seasons");}
using(var doc=JsonDocument.Parse("{\"id\":304,\"mediaType\":\"tv\",\"name\":\"Complete Show\",\"firstAirDate\":\"2022-05-01\",\"voteCount\":100}")){Check(!Projection.ShouldIncludeBrowseItem(doc.RootElement,"tv",new DateOnly(2026,11,6),null,new HashSet<int>{304}),"Owned series without partial-season status is excluded from Discover");}
using(var doc=JsonDocument.Parse("{\"id\":550,\"title\":\"Fight Club\",\"tagline\":\"Mischief. Mayhem. Soap.\",\"runtime\":139,\"voteAverage\":8.43,\"status\":\"Released\",\"genres\":[{\"name\":\"Drama\"},{\"name\":\"Thriller\"}],\"releases\":{\"results\":[{\"iso_3166_1\":\"US\",\"release_dates\":[{\"certification\":\"R\"}]}]},\"credits\":{\"crew\":[{\"job\":\"Director\",\"name\":\"David Fincher\"}],\"cast\":[{\"name\":\"Brad Pitt\"},{\"name\":\"Edward Norton\"}]}}")){var json=JsonSerializer.Serialize(Projection.Details(doc.RootElement,"movie"));Check(json.Contains("David Fincher")&&json.Contains("Mischief. Mayhem. Soap.")&&json.Contains("\"runtime\":139")&&json.Contains("\"certification\":\"R\""),"Movie details projection captures rich metadata");}
using(var doc=JsonDocument.Parse("{\"criticsScore\":86,\"criticsRating\":\"Certified Fresh\",\"audienceScore\":91,\"audienceRating\":\"Upright\"}")){var rt=JsonSerializer.Serialize(Projection.MovieRatings(doc.RootElement));Check(rt.Contains("\"criticsScore\":86")&&rt.Contains("Certified Fresh")&&rt.Contains("\"audienceScore\":91"),"Movie ratings projection parses Rotten Tomatoes scores");}
using(var doc=JsonDocument.Parse("{\"server\":{\"id\":0,\"is4k\":false,\"isDefault\":true,\"activeProfileId\":15,\"activeDirectory\":\"/data/movies\"},\"profiles\":[{\"id\":12,\"name\":\"1080p Efficient\"},{\"id\":15,\"name\":\"1080p Quality\"}]}")){var profs=Projection.ParseProfiles(doc.RootElement,0,"",false,false,0);Check(profs.Length==2&&profs[1].Id==15&&profs[1].IsDefault&&!profs[0].IsDefault&&profs[1].RootFolder=="/data/movies","Quality profile parser extracts profiles and marks active default");}
using(var doc=JsonDocument.Parse("{\"id\":101,\"mediaType\":\"movie\",\"title\":\"Already Downloaded\",\"releaseDate\":\"2022-05-01\",\"voteCount\":100,\"mediaInfo\":{\"status\":5}}")){Check(Projection.ShouldIncludeBrowseItem(doc.RootElement,"movie",new DateOnly(2026,11,6),null,null,allowOwned:true),"Search browse includes already downloaded status=5 movies");}
using(var doc=JsonDocument.Parse("{\"id\":202,\"mediaType\":\"movie\",\"title\":\"In Jellyfin Library\",\"releaseDate\":\"2022-05-01\",\"voteCount\":100}")){Check(Projection.ShouldIncludeBrowseItem(doc.RootElement,"movie",new DateOnly(2026,11,6),new HashSet<int>{202},null,allowOwned:true),"Search browse includes playable Jellyfin library movies");}
using(var doc=JsonDocument.Parse("{\"mediaInfo\":{\"status\":3,\"requests\":[{\"id\":256,\"status\":2,\"is4k\":false,\"profileId\":15,\"requestedBy\":{\"id\":17,\"email\":\"private@example.com\"},\"seasons\":[]},{\"id\":257,\"status\":3,\"requestedBy\":{\"id\":17}}]}}")){var reqJson=JsonSerializer.Serialize(Projection.ActiveRequests(doc.RootElement,17));Check(reqJson.Contains("\"id\":256")&&reqJson.Contains("\"canCancel\":true")&&!reqJson.Contains("257")&&!reqJson.Contains("private@example.com"),"ActiveRequests keeps pending/approved requests, excludes declined and strips PII");}
using(var doc=JsonDocument.Parse("{\"id\":1317288,\"title\":\"The Hunger Games: Sunrise on the Reaping\",\"tagline\":null,\"runtime\":null,\"voteAverage\":null,\"status\":\"Post Production\",\"genres\":null,\"releases\":null,\"credits\":null,\"mediaInfo\":{\"status\":2,\"requests\":[{\"id\":99,\"status\":2,\"is4k\":false,\"profileId\":null,\"requestedBy\":{\"id\":17},\"seasons\":null}]}}")){var detJson=JsonSerializer.Serialize(Projection.Details(doc.RootElement,"movie"));var reqJson=JsonSerializer.Serialize(Projection.ActiveRequests(doc.RootElement,17));Check(detJson.Contains("Sunrise on the Reaping")&&detJson.Contains("\"runtime\":0")&&reqJson.Contains("\"id\":99")&&reqJson.Contains("\"profileId\":null")&&reqJson.Contains("\"canCancel\":true"),"Legacy requests with null profileId and upcoming movies with null runtime/voteAverage parse without throwing");}
using(var doc=JsonDocument.Parse("{\"criticsScore\":null,\"criticsRating\":null,\"audienceScore\":null,\"audienceRating\":null}")){Check(Projection.MovieRatings(doc.RootElement)is null,"Null Rotten Tomatoes scores return null cleanly without throwing");}
using(var doc=JsonDocument.Parse("{\"id\":999,\"name\":\"Upcoming Series\",\"episodeRunTime\":[null,45],\"numberOfSeasons\":null,\"numberOfEpisodes\":null}")){var tvJson=JsonSerializer.Serialize(Projection.Details(doc.RootElement,"tv"));Check(tvJson.Contains("\"runtime\":45")&&tvJson.Contains("\"numberOfSeasons\":0"),"TV details with null season counts and null episodeRunTime entries parse cleanly");}
var handler=new FakeHandler();using var gateway=new SeerrGateway(handler);
using(var doc=await gateway.Send(links[0],"discover/movies?page=1",null,CancellationToken.None)){Check(handler.User=="17"&&handler.Key=="server-secret","Upstream request always carries mapped user plus server-only key");Check(handler.Url=="http://host/api/v1/discover/movies?page=1","Fixed API base and permitted path");}
using(var doc=await gateway.SendAdmin("service/radarr",CancellationToken.None)){Check(handler.User is null&&handler.Key=="server-secret","Admin service metadata request omits X-API-User and carries server key");}
await gateway.Delete(links[0],"request/256",CancellationToken.None);Check(handler.Method=="DELETE"&&handler.User=="17"&&handler.Url=="http://host/api/v1/request/256","Delete sends authenticated DELETE with mapped user");
for(int i=0;i<10;i++)Check(gateway.PermitWrite(a),"Allowed write within rate cap");Check(!gateway.PermitWrite(a)&&gateway.PermitWrite(b),"Write cap is per Jellyfin user");
Console.WriteLine($"{checks} Request Hub security and delivery checks passed.");
class FakeHandler:HttpMessageHandler{public string? User,Key,Url,Method;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Method=request.Method.Method;User=request.Headers.TryGetValues("X-API-User",out var u)?u.Single():null;Key=request.Headers.GetValues("X-API-Key").Single();Url=request.RequestUri!.AbsoluteUri;return Task.FromResult(new HttpResponseMessage(request.Method==HttpMethod.Delete?HttpStatusCode.NoContent:HttpStatusCode.OK){Content=request.Method==HttpMethod.Delete?null:new StringContent("{\"results\":[]}")});}}
